// The build-time emitter's pure core: builds the bench on both tiers and returns every generated file as a string,
// keyed by its path from the repo root. scripts/emit.ts writes them; nothing here touches the filesystem.
import {
  BENCH_SEED_TEXT, KIND, MACHINE, MACHINE_NAMES, buildBench, evaluatePose, generateOU, hashString, heroPlateSvg, inkPlateSvg,
  projectParts, type LayoutResult, type MachineId, type PartInstance, type Pose, type ProjectedPart, type Tier,
} from '@/bench';

const HEADER = '// generated by scripts/emit.ts — do not edit\n';

/** Reference aspects the hero plates are projected at; the page rescales x by referenceAspect / currentAspect. */
const HERO_ASPECT = { landscape: 1.6, portrait: 0.462 } as const;
/** The og image's frame and its rect budget. */
const POSTER = { width: 1200, height: 630, maxRects: 800 } as const;
const PLATE_CAP = 2500;

const TONE = { ink: 0, pencil: 1, hot: 2 } as const;
type Tone = (typeof TONE)[keyof typeof TONE];
/** [x, y, w, h, tone] in poster pixels, y down. */
export type PosterRect = [number, number, number, number, Tone];

function pose(section: number, u: number, tier: Tier): Pose {
  const out = { position: [0, 0, 0], lookAt: [0, 0, 0], fov: 0 };
  evaluatePose(section, u, tier, out);
  const [px, py, pz] = out.position, [lx, ly, lz] = out.lookAt;
  return { position: [px, py, pz], lookAt: [lx, ly, lz], fov: out.fov };
}

/** The hero draws the quoter and the intake in pencil, the bot in ink, and crops the small machines at the frame edge. */
const HERO_OPTS = {
  inkMachines: [MACHINE.bot],
  pencilMachines: [MACHINE.quoter, MACHINE.intake],
  cropMachines: [MACHINE.balance, MACHINE.splitter, MACHINE.watch, MACHINE.slot],
};

/** A single-quoted TS literal. The plates are built from numbers and fixed markup, so nothing in them needs escaping; refuse rather than escape if that ever changes. */
function literal(s: string): string {
  if (/['\\\n\r\u2028\u2029]/.test(s)) throw new Error('emit: plate markup would need escaping');
  return `'${s}'`;
}

const num = (n: number) => String(n);
const vec = (v: readonly number[]) => `[${v.map(num).join(', ')}]`;
const poseLiteral = (p: Pose) => `{ position: ${vec(p.position)}, lookAt: ${vec(p.lookAt)}, fov: ${num(p.fov)} }`;

/**
 * The quoter's quoted cells at machine time 0 with the bed unmerged, as cell.glsl.ts flags them hot: in each column
 * (market = column, OU step 0), the rows at the bid and ask offsets either side of the mid.
 */
function quotedCell(ou: Uint8Array): (p: PartInstance) => boolean {
  return (p) => {
    if (p.machine !== MACHINE.quoter || p.kind !== KIND.cell) return false;
    const i = p.param[0] * 4, mid = ou[i], row = p.param[1];
    return row === mid - ou[i + 1] || row === mid + ou[i + 2];
  };
}

/** Ink everywhere the page is scrolled past, as layout's inkedAtEnd counts it: the slot and the visitor stay pencil. */
function toneOf(p: PartInstance, quoted: (p: PartInstance) => boolean): Tone {
  if (p.machine === MACHINE.slot || p.machine === MACHINE.visitor) return TONE.pencil;
  return quoted(p) ? TONE.hot : TONE.ink;
}

const EMPTY = 255;

/** Paints each part's projected box (rotated for bars and rods) in the given order, later over earlier, into a grid of g-pixel squares sampled at their centres. */
function paint(parts: ProjectedPart[], tones: Tone[], g: number): { grid: Uint8Array; cols: number; rows: number } {
  const { width: W, height: H } = POSTER;
  const cols = Math.ceil(W / g), rows = Math.ceil(H / g);
  const grid = new Uint8Array(cols * rows).fill(EMPTY);
  parts.forEach((r, k) => {
    const a = (r.angle * Math.PI) / 180, ca = Math.cos(a), sa = Math.sin(a), hw = r.w / 2, hh = r.h / 2;
    const ex = Math.abs(ca) * hw + Math.abs(sa) * hh, ey = Math.abs(sa) * hw + Math.abs(ca) * hh;
    const i0 = Math.max(0, Math.floor(((r.x - ex + 1) / 2) * W / g)), i1 = Math.min(cols - 1, Math.floor(((r.x + ex + 1) / 2) * W / g));
    const j0 = Math.max(0, Math.floor(((1 - r.y - ey) / 2) * H / g)), j1 = Math.min(rows - 1, Math.floor(((1 - r.y + ey) / 2) * H / g));
    for (let j = j0; j <= j1; j++) {
      const dy = 1 - (((j + 0.5) * g) / H) * 2 - r.y;
      for (let i = i0; i <= i1; i++) {
        const dx = (((i + 0.5) * g) / W) * 2 - 1 - r.x;
        if (Math.abs(dx * ca + dy * sa) <= hw && Math.abs(dy * ca - dx * sa) <= hh) grid[j * cols + i] = tones[k];
      }
    }
  });
  return { grid, cols, rows };
}

/** Each row's same-tone runs, merged down into the rect above while the run keeps its extent. Disjoint, so paint order does not matter. */
function mergeRuns(grid: Uint8Array, cols: number, rows: number, g: number): PosterRect[] {
  const { width: W, height: H } = POSTER;
  const out: PosterRect[] = [];
  let open = new Map<string, PosterRect>();
  for (let j = 0; j < rows; j++) {
    const next = new Map<string, PosterRect>();
    for (let i = 0; i < cols;) {
      const t = grid[j * cols + i];
      let k = i + 1;
      while (k < cols && grid[j * cols + k] === t) k++;
      if (t !== EMPTY) {
        const key = `${i},${k},${t}`;
        let r = open.get(key);
        if (r) r[3] = Math.min(H, (j + 1) * g) - r[1];
        else out.push((r = [i * g, j * g, Math.min(W, k * g) - i * g, Math.min(H, (j + 1) * g) - j * g, t as Tone]));
        next.set(key, r);
      }
      i = k;
    }
    open = next;
  }
  return out;
}

/**
 * The poster frame as flat tone rects for the og image: every part at the poster pose painted far to near, so nearer
 * parts cover farther ones, then merged into runs. The grid is the finest whole pixel that fits the rect budget.
 */
export function posterRects(result: LayoutResult, at: Pose): PosterRect[] {
  const quoted = quotedCell(generateOU(hashString(BENCH_SEED_TEXT)));
  const parts = projectParts(result, at, POSTER.width / POSTER.height)
    .filter((r) => Number.isFinite(r.x) && Number.isFinite(r.y) && r.depth >= -1 && r.depth <= 1)
    .sort((a, b) => b.depth - a.depth);
  const tones = parts.map((r) => toneOf(r.part, quoted));
  for (let g = 1; ; g++) {
    const { grid, cols, rows } = paint(parts, tones, g);
    const rects = mergeRuns(grid, cols, rows, g);
    if (rects.length <= POSTER.maxRects) return rects;
  }
}

/** Every generated file, keyed by its path from the repo root. Deterministic: two runs return identical strings. */
export function emitAll(): { files: Record<string, string> } {
  const desktop = buildBench('desktop'), phone = buildBench('phone');
  const hero = pose(0, 0, 'desktop'), heroPortrait = pose(0, 0, 'phone'), poster = pose(7, 0.6, 'desktop');
  const files: Record<string, string> = {};

  files['src/generated/heroPlate.ts'] = HEADER + [
    `export const HERO_ASPECT_LANDSCAPE = ${num(HERO_ASPECT.landscape)};`,
    `export const HERO_ASPECT_PORTRAIT = ${num(HERO_ASPECT.portrait)};`,
    `export const HERO_PLATE_LANDSCAPE = ${literal(heroPlateSvg(desktop, hero, HERO_ASPECT.landscape, HERO_OPTS))};`,
    `export const HERO_PLATE_PORTRAIT = ${literal(heroPlateSvg(phone, heroPortrait, HERO_ASPECT.portrait, HERO_OPTS))};`,
  ].join('\n') + '\n';

  files['src/generated/posterPlate.ts'] = HEADER + [
    '/** The poster frame for the og image: [x, y, w, h, tone] in 1200 × 630 px, y down, disjoint; tone 0 = ink, 1 = pencil, 2 = hot. */',
    'export const POSTER_RECTS: Array<[number, number, number, number, 0 | 1 | 2]> = [',
    ...posterRects(desktop, poster).map((r) => `  ${vec(r)},`),
    '];',
  ].join('\n') + '\n';

  const tierCounts = (r: LayoutResult) => `{ total: ${r.counts.total}, inkedAtEnd: ${r.counts.inkedAtEnd}, byMachine: ${vec(r.counts.byMachine)} }`;
  files['src/generated/counts.ts'] = HEADER + [
    '/** Every part count the page prints, per tier, from the layout. byMachine is indexed by MachineId. */',
    'export const COUNTS = {',
    `  desktop: ${tierCounts(desktop)},`,
    `  phone: ${tierCounts(phone)},`,
    '} as const;',
  ].join('\n') + '\n';

  files['src/generated/poses.ts'] = HEADER + [
    "import type { Pose } from '@/bench/camera';",
    '',
    '/** The camera poses the hero plates and the poster were projected from. */',
    'export const EMITTED_POSES: { hero: Pose; heroPortrait: Pose; poster: Pose } = {',
    `  hero: ${poseLiteral(hero)},`,
    `  heroPortrait: ${poseLiteral(heroPortrait)},`,
    `  poster: ${poseLiteral(poster)},`,
    '};',
  ].join('\n') + '\n';

  // quoter, intake and bot at the hero pose; the rest at their own section's pose.
  const platePoses: [MachineId, Pose][] = [
    [MACHINE.quoter, hero], [MACHINE.intake, hero], [MACHINE.bot, hero],
    [MACHINE.balance, pose(4, 0.7, 'desktop')], [MACHINE.splitter, pose(5, 0.7, 'desktop')],
    [MACHINE.watch, pose(6, 0.7, 'desktop')], [MACHINE.slot, pose(8, 0.6, 'desktop')],
  ];
  for (const [m, at] of platePoses) files[`public/plates/${MACHINE_NAMES[m]}.svg`] = inkPlateSvg(desktop, m, at, HERO_ASPECT.landscape, PLATE_CAP) + '\n';

  return { files };
}
